<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { riskApi } from '../api/risk'
const alerts=ref<any[]>([]),error=ref(''),loading=ref(true),working=ref(''),selected=ref<any>(null)
const form=ref({status:'resolved',assessment_result:'cleared_after_review',assessment_note:'',customer_consulted:false,customer_consultation_note:'',disposition_code:'NO_ACTION',disposition_note:''})
async function load(){loading.value=true;try{alerts.value=(await riskApi.alerts()).data.data.items}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{loading.value=false}}
async function take(a:any){working.value=a.id;try{await riskApi.handle(a.id,{status:'acknowledged',note:'管理员已接单'});await load()}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{working.value=''}}
function openProcess(a:any){selected.value=a;form.value={status:'resolved',assessment_result:'cleared_after_review',assessment_note:'',customer_consulted:false,customer_consultation_note:'',disposition_code:'NO_ACTION',disposition_note:''}}
async function submit(){if(!selected.value)return;working.value=selected.value.id;try{await riskApi.handle(selected.value.id,form.value);selected.value=null;await load()}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{working.value=''}}
onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">RISK CONTROL</span><h2>风险预警</h2><p>接单后记录评估结论、客户沟通和实际处置。</p></div><span class="table-summary">{{alerts.length}} 条</span></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取风险预警…</div><div v-else class="module-table-wrap"><table class="admin-table"><thead><tr><th>客户</th><th>规则</th><th>等级</th><th>证据</th><th>评估</th><th>处置</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in alerts" :key="a.id"><td>{{a.customer_name||'未知客户'}}</td><td>{{a.rule_code}}</td><td>{{a.alert_level}}</td><td class="truncate-cell">{{a.recommendation}}；{{JSON.stringify(a.evidence)}}</td><td>{{a.assessment_result||'待评估'}}<small>{{a.assessment_note}}</small></td><td>{{a.disposition_code||'未处置'}}<small>{{a.disposition_note}}</small></td><td><span class="status-badge" :class="a.status">{{a.status}}</span></td><td><button v-if="a.status==='open'" class="table-action" :disabled="working===a.id" @click="take(a)">接单</button><button v-if="a.status==='acknowledged'" class="table-action" :disabled="working===a.id" @click="openProcess(a)">评估处理</button></td></tr><tr v-if="!alerts.length"><td colspan="8" class="table-empty">暂无风险预警</td></tr></tbody></table></div><Teleport to="body"><div v-if="selected" class="admin-modal-backdrop risk-process-backdrop" @click.self="selected=null"><div class="admin-modal risk-process-modal"><h3>风险预警评估与处置</h3><label>评估结论<select v-model="form.assessment_result"><option value="cleared_after_review">评估后通过</option><option value="confirmed_risk">确认风险</option><option value="false_positive">误报</option><option value="insufficient_information">信息不足</option></select></label><label>评估说明<textarea v-model="form.assessment_note" /></label><label><input type="checkbox" v-model="form.customer_consulted" /> 已与客户沟通</label><label>沟通记录<textarea v-model="form.customer_consultation_note" /></label><label>实际处置<select v-model="form.disposition_code"><option value="NO_ACTION">确认通过/无需限制</option><option value="REQUEST_MATERIALS">要求补充材料</option><option value="HOLD_ORDER">挂起订单</option><option value="REJECT_ORDER">拒绝订单</option><option value="RESTRICT_TRADING">限制交易</option><option value="CREATE_INVESTIGATION">创建调查工单</option><option value="CREATE_REPORT_DRAFT">生成报告草稿</option><option value="ESCALATE">升级处理</option></select></label><label>处置说明<textarea v-model="form.disposition_note" /></label><div><button @click="selected=null">取消</button><button class="primary" :disabled="working===selected.id" @click="submit">保存评估与处置</button></div></div></div></Teleport></section></template>

